 CREATE OR REPLACE FUNCTION public.getcwdashboard(userid character varying)                                                                                                                                                                                            
  RETURNS TABLE(totalcount bigint, open bigint, closed bigint, cancelled bigint, closedtoday bigint, closedthisweek bigint, averageclosurerate bigint, overdue bigint, ir bigint, ar bigint, totalassignedcases bigint, totalacceptedcases bigint, tobeaccepted bigint)
  LANGUAGE plpgsql                                                                                                                                                                                                                                                     
 AS $function$                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                       
 BEGIN                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                       
 RETURN QUERY                                                                                                                                                                                                                                                          
 SELECT count(*) as TotalCount                                                                                                                                                                                                                                         
 ,COUNT(CASE WHEN ISRS.description != 'Closed' AND ISRS.description != 'Cancelled' AND ISRS.description != 'Completed'THEN 1 END) as Open                                                                                                                              
 ,COUNT(CASE WHEN ISRS.description = 'Closed' THEN 1 END) as Closed                                                                                                                                                                                                    
 ,COUNT(CASE WHEN ISRS.description = 'Cancelled' THEN 1 END) as Cancelled                                                                                                                                                                                              
 ,COUNT(CASE WHEN ISR.insertedon::date = now()::date AND ISRS.description = 'Closed' THEN 1 END) as ClosedToday                                                                                                                                                        
 ,COUNT(CASE WHEN (ISR.insertedon::date <= now()::date AND ISR.insertedon::date >= now()::date-7)AND ISRS.description = 'Closed' THEN 1 END) as ClosedThisWeek                                                                                                         
 ,COUNT(CASE WHEN (ISR.insertedon::date <= now()::date AND ISR.insertedon::date >= now()::date-90)AND ISRS.description = 'Closed' THEN 1 END)/3 as AverageClosureRate                                                                                                  
 ,COUNT(ISR.insertedon::date + SRT.DueDateOffset::integer) as overdue                                                                                                                                                                                                  
 ,COUNT(CASE WHEN ISR.actiontype ='IR' THEN 1 END) AS IrCount                                                                                                                                                                                                          
 ,COUNT(CASE WHEN ISR.actiontype ='AR' THEN 1 END) AS ArCount                                                                                                                                                                                                          
 ,COUNT(CASE WHEN ISR.isrouted ='t' THEN 1 END) AS TotalAssignedCase                                                                                                                                                                                                   
 ,COUNT(CASE WHEN ISRS.description='Accepted' THEN 1 END) AS TotalAcceptedCases                                                                                                                                                                                        
 ,COUNT(CASE WHEN ISR.isaccepted ='f' THEN 1 END) AS ToBeAccepted                                                                                                                                                                                                      
 FROM intakeservicerequest AS ISR                                                                                                                                                                                                                                      
 JOIN (select intakeserviceid, max(actorid::character varying) ::uuid actorid                                                                                                                                                                                          
         FROM intakeservicerequestactor                                                                                                                                                                                                                                
         WHERE intakeservicerequestpersontypekey in ('CLI', 'RC','RA', 'Youth' ,'2085')                                                                                                                                                                                
         AND activeflag =1 group by intakeserviceid )as ISRA                                                                                                                                                                                                           
         ON ISRA.intakeserviceid=ISR.intakeserviceid                                                                                                                                                                                                                   
 JOIN actor a on a.actorid = ISRA.actorid and a.activeflag =1                                                                                                                                                                                                          
 JOIN person p on p.personid = a.personid and p.activeflag = 1                                                                                                                                                                                                         
 JOIN IntakeSerReqStatusType AS ISRS ON ISR.IntakeSerReqStatusTypeId = ISRS.IntakeSerReqStatusTypeId and ISRS.activeflag=1  and ISR.activeflag = 1                                                                                                                     
 JOIN Routing AS R ON R.objectid  = ISR.IntakeServiceId :: character varying AND R.ActiveFlag = 1                                                                                                                                                                      
 JOIN ServiceRequestTypeConfig AS SRT ON ISR.IntakeServReqTypeId = SRT.IntakeServReqTypeId                                                                                                                                                                             
 AND ISR.IntakeServiceRequestClassId = SRT.ServiceRequestSubTypeId                                                                                                                                                                                                     
 AND SRT.duedateoffset > 0 AND SRT.ACTIVEFLAG=1                                                                                                                                                                                                                        
 where R.tosecurityusersid = userid ;                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                       
  END;                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                       
 $function$                                                                                                                                                                                                                                                            

